/// Real dispatch for every method declared in `netmaker_schema()`. Mirrors
/// `zeroclaw::dispatch_zeroclaw_method`'s role — the plugin crate owns its
/// own dispatch, the gRPC bridge just calls this one function.
pub async fn dispatch_netmaker_method(method: &str, args: &JsonValue) -> Result<JsonValue> {
    let plugin = NetmakerPlugin::new(NetmakerConfig::default());
    match method {
        "join_network" => {
            let network = args
                .get("network")
                .and_then(|v| v.as_str())
                .context("network required")?;
            let token = args.get("token").and_then(|v| v.as_str()).unwrap_or("");
            plugin.join_network(network, token).await?;
            Ok(json!({ "joined": network }))
        }
        "leave_network" => {
            let network = args
                .get("network")
                .and_then(|v| v.as_str())
                .context("network required")?;
            plugin.leave_network(network).await?;
            Ok(json!({ "left": network }))
        }
        "list_networks" => NetmakerPlugin::list_networks_api().await,
        "list_nodes" => {
            let network = args
                .get("network")
                .and_then(|v| v.as_str())
                .context("network required")?;
            NetmakerPlugin::list_nodes_api(network).await
        }
        "get_node" => {
            let network = args
                .get("network")
                .and_then(|v| v.as_str())
                .context("network required")?;
            let node_id = args
                .get("node_id")
                .and_then(|v| v.as_str())
                .context("node_id required")?;
            NetmakerPlugin::get_node_api(network, node_id).await
        }
        "update_node" => {
            let network = args
                .get("network")
                .and_then(|v| v.as_str())
                .context("network required")?;
            let node_id = args
                .get("node_id")
                .and_then(|v| v.as_str())
                .context("node_id required")?;
            let payload = args.get("payload").cloned().unwrap_or(json!({}));
            NetmakerPlugin::update_node_api(network, node_id, &payload).await
        }
        _ => anyhow::bail!("unknown netmaker method: {method}"),
    }
}

// Self-registration: the plugin registry discovers this via inventory
// (single source of the catalog; no central dispatch list).
inventory::submit! {
    crate::default_registry::PluginReg::new("netmaker", |_ctx| std::sync::Arc::new(NetmakerPlugin::new(NetmakerConfig::default())))
}

//! OCI container plugin — schema-driven lifecycle for Docker/OCI containers
//! managed by incus that need host-side bootstrap (loopback, netns init).
//!
//! OCI containers in incus with no NIC device boot with lo DOWN, preventing
//! services from binding to 127.0.0.1. This plugin declares which containers
//! need loopback bring-up, and the `rovs_commands` plugin handles the OVS
//! control-plane work.
//! D-Bus method executes it.
//!
//! THE PLUGIN IS THE SCHEMA — if a container is declared here with
//! loopback_required=true, the daemon will bring up lo inside its netns.
//!
//! D-Bus methods: https://docs.docker.com/engine/api/v1.45/

use anyhow::Result;
use op_state::{ApplyResult, Checkpoint, DiffMetadata, PluginCapabilities, StateDiff, StatePlugin};
use op_state_store::{Constraint, FieldSchema, FieldType, PluginSchema, ReadOnlyCondition};
use schemars::JsonSchema;
use serde::{Deserialize, Serialize};
use simd_json::json;
use simd_json::OwnedValue as Value;
use std::collections::HashMap;

// ── Schema definition — THE PLUGIN IS THE SCHEMA ─────────────────────────────

fn oci_container_fields() -> HashMap<String, FieldSchema> {
    let mut fields = HashMap::new();
    fields.insert(
        "name".to_string(),
        FieldSchema {
            field_type: FieldType::String,
            required: true,
            description: "Incus instance name (must match hostname inside container)".to_string(),
            default: None,
            example: Some(json!("netmaker")),
            constraints: Vec::new(),
            read_only: true,
            read_only_when: None,
        },
    );
    fields.insert(
        "image".to_string(),
        FieldSchema {
            field_type: FieldType::String,
            required: true,
            description: "OCI image reference (e.g. docker:gravitl/netmaker:v1.5.1)".to_string(),
            default: None,
            example: Some(json!("docker:gravitl/netmaker:v1.5.1")),
            constraints: Vec::new(),
            read_only: false,
            read_only_when: None,
        },
    );
    fields.insert(
        "loopback_required".to_string(),
        FieldSchema {
            field_type: FieldType::Boolean,
            required: false,
            description: "Whether BringUpLoopback must run inside this container's netns before services start. Required for OCI containers with no NIC.".to_string(),
